const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const organization=new URL(location.href).searchParams.get('organization');let s,a,csrf,busy=false,lastFocus,view=location.hash.slice(1)||'droits',filter='received',reading=null,previewing=null,previewEpoch=0,state=null,support=null,registry=null,partners=null,modules=null,platformRole=null,trash=null,audiences={manage:false,members:[],options:[]};
const audienceLabels={none:'Aucun accès Agenda',elus:'Élus seulement',adherents:'Élus et adhérents',public:'Tous les salariés'};
const labels={document_review:'Valider un document',document_publish:'Diffuser un document',dossiers_assign:'Affectation des dossiers',agenda_review:'Valider un ordre du jour',agenda_publish:'Diffuser un ordre du jour',agenda_convocation:'Convocations Agenda',agenda_audience:'Administration des audiences Agenda',rights:'Gestion des habilitations',share:'Partage entre organisations',accept:'Acceptation des partages',download:'Téléchargement contrôlé',history:'Ouverture de l’historique',organization_edit:'Modification de l’organisation',read:'Lecture',write:'Modification',create:'Création'};
const has=p=>(a.authorities||[]).some(x=>x.permission===p),day=()=>new Date(Date.now()+7*86400000).toISOString().slice(0,16);
async function request(path,data={}){const r=await fetch(path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Uniion-CSRF':csrf},body:JSON.stringify((path==='/identity/organizations'||path==='/identity/platform-role'||path.startsWith('/identity/support-agents')||path.startsWith('/identity/partners'))?data:{organization_id:organization,...data})});if(!r.ok)throw Error('Accès refusé ou service indisponible.');return r.json();}
function notice(msg){$('#notice').hidden=false;$('#notice').innerHTML='<span>'+esc(msg)+'</span><button data-action="dismiss" aria-label="Fermer la notification">×</button>';}
function close(){reading=null;previewing=null;previewEpoch++;$('#modal').close();$('#modal-body').innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();}
function modal(title,body){lastFocus=document.activeElement;$('#modal-body').innerHTML=`<button class="close" data-action="close" aria-label="Fermer la fenêtre">×</button><h2 id="modal-title">${esc(title)}</h2>${body}`;$('#modal').showModal();}
function heading(title,desc,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="muted">${desc}</p></div>${action}</div>`;}
let loading=Promise.resolve();
function load(){const requested=view;loading=loading.catch(()=>{}).then(async()=>{if(view!==requested)return;await loadView();});return loading;}
async function loadView(){const target=view;if(target==='corbeille'||target==='suppressions'){trash=await trashCall(target==='suppressions'?'admin_list':'list');if(target==='suppressions'){const extra=await trashCall('admin_list',{disposal:true});trash.requests.push(...extra.requests.map(t=>({...t,disposal:true})));}s={user:{},organization:{id:organization,name:target==='suppressions'?'Administration globale':(new URL(location.href).searchParams.get('scope')==='document'?'Corbeille des documents':'Corbeille du dossier')},organizations:[],permissions:[]};a={authorities:[]};if(view===target)show();return;}if(target==='partenaires'){partners=await request('/identity/partners');s={user:{},organization:{id:organization,name:'Administration globale'},organizations:[],permissions:[]};a={authorities:[]};if(view===target)show();return;}if(target==='modules'){modules=await request('/identity/modules');s={user:{},organization:{id:organization,name:modules.organization},organizations:[],permissions:[]};a={authorities:[]};if(view===target)show();return;}if(target==='agents-support'){registry=await request('/identity/support-agents');s={user:{},organization:{id:organization,name:'Administration globale'},organizations:[],permissions:[]};a={authorities:[]};if(view===target)show();return;}if(target==='support'){support=await request('/identity/support');s={user:{id:support.actor},organization:{id:organization,name:support.organization},organizations:[],permissions:[]};a={authorities:[]};if(view===target)show();return;}const p=await request('/identity/profile');const context=await request('/identity/organizations');a=await request('/identity/console');s={user:{id:p.id},organization:{id:organization,name:p.organization},organizations:context.organizations,permissions:context.permissions.filter(x=>x.org===organization)};if(target==='support')support=await request('/identity/support');if(target==='collections')state=await request('/identity/collections');if(target==='droits'){try{audiences=await request('/identity/agenda/audiences');}catch(e){trash=null,audiences={manage:false,members:[],options:[]};}}if(view===target)show();}
async function refresh(){await load();}
const date=x=>new Date(x).toLocaleString('fr-FR');

function collectionsView(){
 const manage=E.has(state,'admin')&&E.has(state,'acceptCollection');
 return heading('Collections de référence','Un héritage volontaire, version par version.',`<button class="primary" data-action="collection-new" ${E.has(state,'publishCollection')&&state.targets.length?'':'disabled'}>Créer une collection</button>`)+`<div class="info">Uniquement des éléments non confidentiels : couleur de référence et texte institutionnel. Aucun accès aux dossiers, membres ou documents métiers de la source. L’identité de cette démonstration ne change pas lorsque vous adoptez une collection.</div><div class="grid">${state.collections.filter(c=>c.source===state.activeOrg||c.target===state.activeOrg).map(c=>{
 const source=c.source===state.activeOrg,published=c.versions.filter(v=>v.published),latest=published.at(-1),sub=c.subscription,accepted=sub&&c.versions.find(v=>v.number===sub.accepted),draft=c.versions.find(v=>!v.published);
 if(source)return `<section class="card"><span class="tag">Votre collection</span><h2>${esc(c.name)}</h2><p>Proposée à ${esc(org(c.target).name)}</p><p>Version publiée : ${latest?'v'+latest.number:'Aucune — première version en validation'}</p>${latest?collectionPreview(latest):''}<div class="actions"><button data-action="col-draft" data-id="${c.id}" ${!E.has(state,'publishCollection')||draft?'disabled':''}>Préparer une mise à jour</button>${draft?`<button data-action="col-review" data-id="${c.id}" ${!E.has(state,'publishCollection')?'disabled':''}>Examiner la version v${draft.number}</button>`:''}</div>${draft?'<p class="muted">En attente d’un second acteur habilité. Invisible pour le destinataire avant publication.</p>':''}</section>`;
 return `<section class="card"><span class="tag">${sub?(sub.active?'Héritage actif':'Suivi arrêté'):'Non adoptée'}</span><h2>${esc(c.name)}</h2><p class="muted">Source : ${esc(org(c.source).name)}</p>${sub?`<p><strong>Version utilisée : v${sub.accepted}</strong></p>${collectionPreview({...accepted,text:sub.overrides.text||accepted.text})}${sub.overrides.text?'<span class="tag good">Adaptation locale conservée</span>':''}`:`<p>Version disponible : v${latest.number}</p><p>Aucun héritage avant votre accord.</p>`}<div class="actions">${!sub?`<button class="primary" data-action="col-adopt" data-id="${c.id}" ${manage?'':'disabled'}>Examiner et adopter</button>`:sub.active?`<button data-action="col-override" data-id="${c.id}" ${manage?'':'disabled'}>Adapter le texte local</button><button data-action="col-stop" data-id="${c.id}" ${manage?'':'disabled'}>Arrêter le suivi</button>`:'<p class="muted">La dernière version acceptée et vos adaptations restent conservées. Aucune nouvelle version ne sera proposée.</p>'}</div>${sub?.active&&latest.number>sub.accepted?`<div class="info"><strong>Version v${latest.number} ${sub.declined.includes(latest.number)?'refusée':'à examiner'}</strong><p>La version v${sub.accepted} reste utilisée tant que vous n’approuvez pas.</p><button data-action="col-compare" data-id="${c.id}" ${manage?'':'disabled'}>${sub.declined.includes(latest.number)?'Réexaminer la mise à jour':'Comparer les versions'}</button></div>`:''}${!manage?'<p class="muted">Administration locale et permission d’adoption nécessaires pour agir.</p>':''}${sub?`<details><summary>Historique des versions acceptées</summary><ul>${sub.history.map(h=>`<li>v${h.version} · ${esc(person(h.actor).name)} · ${date(h.at)}</li>`).join('')}</ul><p>Les versions précédentes restent conservées ; les documents existants ne sont pas réécrits.</p></details>`:''}</section>`;
 }).join('')}</div>`;
}
function createCollectionForm(){if(!E.has(state,'publishCollection')||!state.targets.length)throw Error('Création non autorisée.');modal('Créer une collection',`<form data-form="collection-create"><label class="field"><span>Nom de la collection</span><input name="name" maxlength="160" required></label><label class="field"><span>Organisation destinataire</span><select name="target" required><option value="">Choisir explicitement une organisation</option>${state.targets.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></label><label class="field"><span>Couleur de référence</span><input name="color" pattern="#[0-9a-fA-F]{6}" value="#CC6600" required></label><label class="field"><span>Texte institutionnel non confidentiel</span><textarea name="text" maxlength="400" required></textarea></label><p>Un second acteur habilité doit publier la première version. Le destinataire devra ensuite l’adopter explicitement. Aucun accès aux données métiers.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Soumettre à validation</button></div></form>`);}
function collectionPreview(v){return `<dl class="collection-preview"><dt>Couleur de référence</dt><dd>${esc(v.color)}</dd><dt>Texte institutionnel</dt><dd>${esc(v.text)}</dd></dl>`;}
async function collectionAction(action,id,b){
 const c=state.collections.find(c=>c.id===id);if(!c)throw Error('Collection inconnue.');
 const latest=c.versions.filter(v=>v.published).at(-1),sub=c.subscription;
 if(action==='col-draft')modal('Préparer une mise à jour',`<form data-form="collection-draft" data-id="${id}"><p>Seuls ces champs non confidentiels sont autorisés. Aucun document métier ne peut être joint.</p><label class="field"><span>Couleur de référence</span><input name="color" value="${esc(latest.color)}" pattern="#[0-9a-fA-F]{6}" required></label><label class="field"><span>Texte institutionnel non confidentiel</span><textarea name="text" maxlength="400" required>${esc(latest.text)}</textarea></label><p>Un second acteur habilité devra relire et publier cette version.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Soumettre à validation</button></div></form>`);
 if(action==='col-review'){
 const draft=c.versions.find(v=>!v.published);if(!draft)throw Error('Aucune version en attente.');
 modal('Relire avant publication',`<p>Auteur : ${esc(person(draft.author).name)} · diffusion vers ${esc(org(c.target).name)}.</p><div class="comparison"><section><h3>${latest?'Publiée · v'+latest.number:'Aucune version publiée'}</h3>${latest?collectionPreview(latest):''}</section><section><h3>À publier · v${draft.number}</h3>${collectionPreview(draft)}</section></div><p>Confirmez la relecture et le caractère non confidentiel de ces éléments. Cette publication ne met pas à jour l’organisation destinataire.</p>${draft.author===state.actor?'<div class="info">Vous êtes l’auteur. Un autre acteur disposant de la permission de publication doit valider.</div>':''}<div class="actions"><button data-action="close">Fermer</button><button class="primary" data-action="col-publish-confirm" data-id="${id}" data-version="${draft.number}" ${draft.author===state.actor?'disabled':''}>Valider et publier cette version</button></div>`);
 }
 if(action==='col-adopt')modal('Adopter volontairement la collection',`<p>${esc(c.name)} · ${esc(org(c.source).name)} · ${latest?'v'+latest.number:'Aucune — première version en validation'}</p>${latest?collectionPreview(latest):''}<div class="info">Vous adoptez cette version uniquement. Les mises à jour futures nécessiteront votre approbation. Aucun droit sur les données métiers de la source.</div><div class="actions"><button data-action="close">Annuler</button><button class="primary" data-action="col-adopt-confirm" data-id="${id}" data-version="${latest.number}">Adopter cette version</button></div>`);
 if(action==='col-compare'){
 const old=c.versions.find(v=>v.number===sub.accepted);
 modal('Comparer la mise à jour',`<div class="comparison"><section><h3>Acceptée · v${old.number}</h3>${collectionPreview(old)}</section><section><h3>Proposée · v${latest.number}</h3>${collectionPreview(latest)}</section></div>${sub.overrides.text?`<div class="info"><strong>Votre adaptation locale sera conservée</strong><p>${esc(sub.overrides.text)}</p></div>`:''}<p>Aucune modification des documents existants. Le refus conserve la version actuelle ; vous pourrez réexaminer plus tard.</p><div class="actions"><button data-action="close">Plus tard</button><button data-action="col-decline-confirm" data-id="${id}" data-version="${latest.number}" data-expected="${old.number}">Refuser cette mise à jour</button><button class="primary" data-action="col-accept-confirm" data-id="${id}" data-version="${latest.number}" data-expected="${old.number}">Approuver cette version</button></div>`);
 }
 if(action==='col-override')modal('Adapter le texte local',`<form data-form="collection-override" data-id="${id}"><p>Votre adaptation reste propre à votre organisation et sera préservée lors des mises à jour. Laisser vide rétablit le texte de la version acceptée.</p><label class="field"><span>Texte local non confidentiel</span><textarea name="text" maxlength="400">${esc(sub.overrides.text||'')}</textarea></label><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Enregistrer le texte local</button></div></form>`);
 if(action==='col-stop')modal('Arrêter le suivi de la collection ?',`<p>La version acceptée et vos adaptations restent conservées. Les futures mises à jour ne seront plus proposées. Aucun contenu n’est supprimé.</p><div class="actions"><button data-action="close">Annuler</button><button data-action="col-stop-confirm" data-id="${id}">Confirmer l’arrêt du suivi</button></div>`);
 const ops={'col-publish-confirm':'collectionPublish','col-adopt-confirm':'collectionAdopt','col-accept-confirm':'collectionAccept','col-decline-confirm':'collectionDecline','col-stop-confirm':'collectionStop'};
 if(ops[action]){const ok=await run(ops[action],{collection:id,version:Number(b.dataset.version),expected:Number(b.dataset.expected)});close();if(ok)tell('Décision enregistrée. Seule la version explicitement acceptée est utilisée.');}
}

const E={has:(state,key)=>!!state.permissions[key]};
const org=id=>state.organizations.find(o=>o.id===id)||{name:'Organisation'};
const person=id=>state.people.find(p=>p.id===id)||{name:'Acteur habilité'};
const tell=notice;
async function run(action,input){const data=Object.fromEntries(Object.entries(input).filter(([k,v])=>k!=='collection'&&(typeof v!=='number'||Number.isFinite(v))));if(action==='collectionStop'){delete data.version;delete data.expected;}await request('/identity/collections/change',{collection:input.collection,action,data});await load();return true;}
function status(g){return g.revoked?'Révoqué':Date.parse(g.expires)<=Date.now()?'Expiré':g.accepted?'Actif':'À accepter';}
function show(){
$('#active-name').textContent=s.organization?.name||'Aucune organisation';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';
if(view==='organisations')html=heading('Vos organisations','Chaque espace reste indépendant, sans accès hérité.',platformRole?.superAdmin?'<button data-view="partenaires">Référentiel partenaires</button><button data-view="suppressions">Validations de suppression</button>':'')+'<p class="muted" style="overflow-wrap:anywhere">Votre identifiant pour recevoir un consentement nominatif : <code>'+esc(s.user.id)+'</code></p><div class="grid">'+s.organizations.map(o=>`<section class="card"><h2>${esc(o.name)}</h2><p>Le rattachement ne donne aucun accès aux données de l’autre organisation.</p><button data-org="${o.id}" ${o.id===s.organization?.id?'disabled':''}>${o.id===s.organization?.id?'Organisation actuelle':'Ouvrir cet espace'}</button></section>`).join('')+'</div>';
else if(view==='droits')html=heading('Droits & membres','Des responsabilités distinctes, attribuées explicitement.')+'<div class="info">Une permission métier ne donne pas accès à toutes les ressources. Les autorisations par ressource et l’historique restent séparés. Vous ne pouvez pas modifier vos propres droits.</div>'+(has('rights')?'<section class="card">'+a.members.map(m=>`<div class="row"><span class="badge">${esc(m.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(m.name)}${m.id===s.user.id?' · vous':''}</h3>${m.authorities.map(p=>`<span class="tag">${esc(labels[p])}</span>`).join('')}${m.permissions.map(p=>`<span class="tag">${esc(p.module)} · ${esc(labels[p.permission])}</span>`).join('')}</div><button data-rights="${m.id}" ${m.id===s.user.id?'disabled':''}>Modifier les droits</button></div>`).join('')+'</section>':'<div class="empty">La gestion des habilitations nécessite une autorisation spécifique.</div>');
else if(view==='partages'){
const incoming=filter==='received',shares=a.shares.filter(g=>incoming?g.target===s.organization.id:g.source===s.organization.id);
html=heading('Partages entre organisations','Lecture seule, personnes désignées et durée limitée.',`${has('rights')&&has('share')?'<button data-action="directory">Visibilité des contacts</button>':''}<button class="primary" data-action="new-share" ${has('share')?'':'disabled'}>Nouveau partage</button>`)+`<div class="tabs"><button data-filter="received" class="${incoming?'active':''}">Reçus</button><button data-filter="sent" class="${!incoming?'active':''}">Envoyés</button></div><div class="grid">`+shares.map(g=>`<section class="card"><span class="tag ${status(g)==='Actif'?'good':'warn'}">${status(g)}</span><h2>${esc(incoming?g.source_name:g.target_name)}</h2><ul>${(g.items||[]).map(r=>`<li>${esc(r.title)} · version ${r.version}</li>`).join('')}</ul><p class="muted">Expiration : ${date(g.expires)}<br>Téléchargement : ${g.download?'autorisé séparément':'interdit'}<br>Bénéficiaires ${g.accepted?'retenus':'proposés'} : ${g.people.filter(p=>(g.accepted?g.beneficiaries:g.allowed).includes(p.id)).map(p=>esc(p.name)).join(', ')}</p><div class="actions">${incoming&&status(g)==='À accepter'&&has('accept')?`<button class="primary" data-accept="${g.id}">Examiner et accepter</button>`:''}${!incoming&&!g.revoked&&has('share')?`<button class="danger" data-revoke="${g.id}">Révoquer le partage</button>`:''}${incoming&&(g.items||[]).some(r=>r.readable)?'<button data-view="ressources">Consulter les ressources</button>':''}</div></section>`).join('')+'</div>'+(shares.length?'':'<div class="empty">Aucun partage accessible dans ce sens.</div>')+'<div class="info">Versions sélectionnées uniquement. Seules les pièces explicitement sélectionnées sont incluses. Aucune mise à jour future ajoutée automatiquement. Aucun repartage, modification ou accès hors ligne. Une copie téléchargée ne peut pas être récupérée après révocation.</div>';
}
else if(view==='corbeille'||view==='suppressions')html=trashView();
else if(view==='partenaires')html=partnersView();
else if(view==='modules')html=modulesView();
else if(view==='agents-support')html=registryView();
else if(view==='support')html=supportView();
else if(view==='collections')html=collectionsView();
else if(view==='journal')html=heading('Journal du parcours','Événements horodatés enregistrés dans Supabase.')+(has('rights')?'<section class="card">'+a.events.map(e=>`<div class="row"><div><h3>${esc(e.event)}</h3><p class="muted">${date(e.at)}</p><p>${esc(JSON.stringify(e.details))}</p></div></div>`).join('')+'</section>':'<div class="empty">Permission de gestion des habilitations requise.</div>');
else if(view==='ressources'){
const shared=a.shares.filter(g=>g.target===s.organization.id).flatMap(g=>(g.items||[]).filter(r=>r.readable).map(r=>({...r,share:g.id,source:g.source_name})));
html=heading('Ressources accessibles','Votre profil et les autorisations actives déterminent ce qui apparaît.')+'<h2>Dans votre organisation</h2><div class="grid">'+a.resources.map(r=>`<section class="card"><span class="tag">${esc(r.module)}</span><h3>${esc(r.title)}</h3><p class="muted">Version ${r.version} · sauvegardée dans Supabase</p><a href="/s02?organization=${encodeURIComponent(organization)}&amp;return=admin">Ouvrir l’application</a><div class="actions"><button data-files="${r.id}">Pièces jointes</button></div></section>`).join('')+'</div><h2>Partagées par une autre organisation</h2><div class="grid">'+shared.map(r=>`<section class="card"><span class="tag">Lecture seule</span><h3>${esc(r.title)}</h3><p class="muted">${esc(r.source)} · version ${r.version}</p><div class="actions"><button data-read="${r.share}" data-resource="${r.id}">Consulter</button><button data-download="${r.share}" data-resource="${r.id}" ${r.downloadable?'':'disabled'}>Télécharger</button></div><p class="muted">Aucun repartage · hors ligne indisponible</p></section>`).join('')+(shared.length?'':'<div class="empty">Aucune ressource partagée accessible.</div>')+'</div>';
}
else html='<div class="empty">Ce parcours reste à raccorder dans S02.</div>';$('#main').innerHTML=html;}
function rights(id){const m=a.members.find(m=>m.id===id);if(!m||id===s.user.id||!has('rights'))throw Error('Modification interdite.');
const own=s.permissions,auth=a.authorities.filter(x=>x.delegable);modal('Habilitations de '+m.name,`<form data-form="rights" data-user="${id}"><fieldset><legend>Permissions métier délégables</legend>${own.map(p=>`<label class="check"><input type="checkbox" name="perm" value="${p.module}:${p.permission}" ${m.permissions.some(x=>x.module===p.module&&x.permission===p.permission)?'checked':''}><span>${esc(p.module)} · ${esc(labels[p.permission])}</span></label>`).join('')}</fieldset><fieldset><legend>Responsabilités séparées</legend>${auth.map(p=>`<label class="check"><input type="checkbox" name="authority" value="${p.permission}" ${m.authorities.includes(p.permission)?'checked':''}><span>${esc(labels[p.permission])}<small>Sans droit de redélégation automatique</small></span></label>`).join('')}</fieldset>${audiences.manage?`<fieldset><legend>Audience Agenda</legend><label class="field"><span>Audience attribuée</span><select name="agenda-audience">${[...new Set([...audiences.options,audiences.members.find(x=>x.user===id)?.audience||'none'])].map(key=>`<option value="${key}" ${key===(audiences.members.find(x=>x.user===id)?.audience||'none')?'selected':''} ${audiences.options.includes(key)?'':'disabled'}>${esc(audienceLabels[key])}</option>`).join('')}</select></label><p class="muted">Audience interne à cette organisation, attribuée jusqu’à révocation. La lecture du module reste distincte ; aucun partage ni téléchargement automatique. L’expiration ci-dessous concerne uniquement les autorisations par ressource.</p></fieldset>`:''}<fieldset><legend>Autorisations par ressource</legend>${a.resources.map(r=>{const g=m.grants.find(g=>g.resource===r.id&&!g.revoked&&Date.parse(g.until)>Date.now());return `<label class="field"><span>${esc(r.title)}</span><select name="resource:${r.id}"><option value="none" ${!g?'selected':''}>Aucun accès</option><option value="read" ${g&&!g.write?'selected':''}>Lecture seule</option>${r.write?`<option value="write" ${g?.write?'selected':''}>Lecture et modification</option>`:''}</select></label>`;}).join('')}<label class="field"><span>Expiration des nouvelles autorisations</span><input type="datetime-local" name="until" value="${day()}" required></label><label class="check"><input type="checkbox" name="history" ${has('history')?'':'disabled'}><span>Ouvrir explicitement l’historique des ressources dont l’autorisation change</span></label></fieldset><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Enregistrer les habilitations</button></div></form>`);
}

function size(n){return n<1024?n+' octets':(n/1024).toLocaleString('fr-FR',{maximumFractionDigits:1})+' Ko';}
function fileRows(list,share=null){const status={pending:'En attente d’analyse',clean:'Analyse validée',infected:'Bloqué par l’antivirus',invalid:'Format bloqué',error:'Analyse indisponible'};return (list||[]).map(f=>`<div class="row"><div style="overflow-wrap:anywhere"><h3>${esc(f.filename)}</h3><span class="tag ${f.scan_status==='clean'?'good':'warn'}">${esc(status[f.scan_status]||'Analyse requise')}</span><span class="muted">${size(f.size)} · ${f.downloadable?'Téléchargement autorisé':'Téléchargement non autorisé'}</span></div><div class="actions"><button data-file-preview="${f.id}" ${share?`data-share="${share}"`:''} data-parent="${f.resource||reading?.resource||''}" ${f.previewable?'':'disabled'}>Aperçu</button><button data-file-download="${f.id}" ${share?`data-share="${share}"`:''} ${f.downloadable?'':'disabled'}>Télécharger la pièce</button>${false?`<button data-file-scan="${f.id}" data-parent="${f.resource}">${f.scan_status==='clean'?'Ré-analyser':'Analyser'}</button>`:''}</div></div>`).join('')||'<p class="muted">Aucune pièce jointe sélectionnée.</p>';}
async function openPreview(id,share,page=1,parent=''){const epoch=++previewEpoch;const d=await request('/identity/attachments/preview',{attachment:id,share,page});if(epoch!==previewEpoch)return;previewing={id,share,parent};modal(d.filename,`<span class="tag">Aperçu · lecture seule · page ${d.page} / ${d.pages}</span><div class="actions"><button data-preview-page="${d.page-1}" ${d.page===1?'disabled':''}>Page précédente</button><button data-preview-page="${d.page+1}" ${d.page===d.pages?'disabled':''}>Page suivante</button><button data-preview-zoom="1">Agrandir</button></div><figure style="margin:16px 0"><img src="${d.image}" alt="Aperçu de ${esc(d.filename)}, page ${d.page}" style="display:block;width:100%;height:auto;max-width:100%;border:1px solid var(--bd);border-radius:12px"></figure><p class="muted">Aperçu rendu en image. Le téléchargement du fichier original nécessite une autorisation distincte.</p><button data-action="close">Fermer</button>`);}


function fileSummary(list){return '<p>Pièces incluses : '+(list?.length?list.map(f=>esc(f.filename)).join(', '):'aucune')+'</p>';}
function shareForm(target){if(!has('share'))throw Error('Permission de partage requise.');const partner=a.partners.find(p=>p.id===target)||a.partners[0];if(!partner)throw Error('Aucune organisation partenaire référencée.');
modal('Proposer un partage',`<form data-form="share"><p>Les versions actuelles sélectionnées seront proposées en lecture seule.</p><label class="field"><span>Organisation destinataire</span><select name="target" id="share-target">${a.partners.map(p=>`<option value="${p.id}" ${p.id===partner.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><fieldset><legend>Ressources à partager</legend>${a.resources.filter(r=>r.shareable).map(r=>`<label class="check"><input type="checkbox" name="resources" value="${r.id}" data-version="${r.version}"><span>${esc(r.title)} · version ${r.version}<small>Pièces jointes à sélectionner séparément</small></span></label>`).join('')||'<p>Aucune ressource autorisée au partage externe.</p>'}</fieldset><fieldset><legend>Pièces jointes à inclure explicitement</legend>${(a.attachments||[]).filter(f=>f.downloadable&&a.resources.some(r=>r.id===f.resource&&r.shareable)).map(f=>`<label class="check"><input type="checkbox" name="attachments" value="${f.id}" data-parent="${f.resource}"><span style="overflow-wrap:anywhere">${esc(f.filename)}<small>${esc(a.resources.find(r=>r.id===f.resource)?.title)} · ${size(f.size)}</small></span></label>`).join('')||'<p class="muted">Aucune pièce jointe disponible.</p>'}<p class="muted">Sélectionnez aussi la ressource associée. Les pièces seront téléchargeables seulement si le téléchargement est autorisé.</p></fieldset><fieldset><legend>Bénéficiaires proposés</legend>${partner.members.map(m=>`<label class="check"><input type="checkbox" name="people" value="${m.id}"><span>${esc(m.name)}</span></label>`).join('')||'<p class="muted">Aucun contact autorisé. Transmettez votre identifiant au partenaire : une personne habilitée doit autoriser leur visibilité depuis « Visibilité des contacts ».</p>'}</fieldset><label class="field"><span>Expiration obligatoire (90 jours maximum)</span><input type="datetime-local" name="until" value="${day()}" required></label><label class="check"><input type="checkbox" name="download" ${has('download')?'':'disabled'}><span>Autoriser le téléchargement<small>Le bénéficiaire devra également avoir la permission de téléchargement. Une copie téléchargée ne pourra pas être récupérée.</small></span></label><div class="info">Le destinataire devra accepter. Aucun accès avant acceptation.</div><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Proposer en lecture seule</button></div></form>`);
}
async function directory(){
if(!has('rights')||!has('share'))throw Error('Gestion des habilitations et partage requis.');
const d=await request('/identity/consents');
modal('Visibilité des contacts',`<p>Autorisez une personne désignée d’une organisation partenaire à voir uniquement les contacts sélectionnés. Cela ne donne aucun accès aux contenus métiers.</p><form data-form="directory"><label class="field"><span>Organisation partenaire</span><select name="target" required>${d.targets.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></label><label class="field"><span>Identifiant de la personne autorisée chez le partenaire</span><input name="grantee" required pattern="[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}" autocomplete="off"><small>Cette personne vous transmet son identifiant affiché dans « Organisations ». Aucun annuaire partenaire n’est ouvert pour cette recherche.</small></label><fieldset><legend>Contacts de votre organisation à rendre visibles</legend>${a.members.map(m=>`<label class="check"><input type="checkbox" name="people" value="${m.id}"><span>${esc(m.name)}</span></label>`).join('')}</fieldset><label class="field"><span>Expiration obligatoire (90 jours maximum)</span><input type="datetime-local" name="until" value="${day()}" required></label><p class="info">Les noms et adresses de ces contacts seront visibles uniquement par la personne désignée, jusqu’à l’expiration ou la révocation. Les partages métiers nécessitent toujours une proposition et une acceptation distinctes.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary" ${d.targets.length?'':'disabled'}>Autoriser la visibilité</button></div></form><h3>Autorisations données</h3>${d.grants.map((g,i)=>`<section class="card" style="overflow-wrap:anywhere"><b>${esc(g.name)}</b><p>${esc(g.target_name)} · destinataire : ${esc(g.grantee)}<br>Expiration : ${date(g.until)}<br>${g.revoked?'Révoquée':Date.parse(g.until)<=Date.now()?'Expirée':'Active'}</p>${!g.revoked&&Date.parse(g.until)>Date.now()?`<button class="danger" data-directory-revoke="${i}">Révoquer cette visibilité</button>`:''}</section>`).join('')||'<p class="muted">Aucune autorisation donnée.</p>'}`);
$('#modal-body').querySelectorAll('[data-directory-revoke]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const g=d.grants[Number(b.dataset.directoryRevoke)];await request('/identity/consents/change',{target:g.target,grantee:g.grantee,people:[g.person],until:g.until,enabled:false});close();await refresh();await directory();notice('Visibilité révoquée. Les partages métiers existants restent soumis à leurs propres autorisations.');}catch(e){notice(e.message,true);b.disabled=false;}});
}
function accept(id){const g=a.shares.find(g=>g.id===id);if(!g||!has('accept'))throw Error('Acceptation interdite.');modal('Accepter le partage',`<form data-form="accept" data-share="${id}"><p>Source : ${esc(g.source_name)} · lecture seule</p><ul>${g.items.map(r=>`<li>${esc(r.title)} · version ${r.version}</li>`).join('')}</ul>${fileSummary(g.attachments)}<p>Expiration : ${date(g.expires)} · téléchargement ${g.download?'soumis aux droits individuels':'interdit'}</p><fieldset><legend>Bénéficiaires autorisés par la source</legend>${g.people.map(p=>`<label class="check"><input type="checkbox" name="people" value="${p.id}"><span>${esc(p.name)}</span></label>`).join('')}</fieldset><p class="muted">Accepter ne vous donne pas accès si vous n’êtes pas bénéficiaire. La liste ne peut pas être élargie.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Accepter pour ces personnes</button></div></form>`);}

document.querySelector('.demo').style.display='none';if(new URL(location.href).searchParams.get('scope')==='document'){const back=document.createElement('a');back.className='backlink document-mobile-back';back.textContent='← Retour aux documents';document.querySelector('.mobile-nav').before(back);}document.querySelectorAll('a').forEach(e=>{e.href='/s02?organization='+encodeURIComponent(organization)+(new URL(location.href).searchParams.get('scope')==='document'?'&screen=documents':'&return=admin');if(new URL(location.href).searchParams.get('scope')==='document'&&e.textContent.includes('Retour au prototype'))e.textContent='← Retour aux documents';});document.querySelectorAll('[data-view="droits"]').forEach(e=>e.classList.add('active'));

async function downloadFile(id,share){const d=await request('/identity/attachments/download',{attachment:id,share});const bytes=Uint8Array.from(atob(d.content),c=>c.charCodeAt(0));saveBlob(new Blob([bytes],{type:d.mime}),d.filename);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function readShared(share,resource){const d=await request('/identity/shares/read',{share,resource,download:false});reading={share,resource};modal(d.title,`<span class="tag">Partage · lecture seule · version ${d.version}</span>${SharedContent.render(d)}<h3>Pièces jointes partagées</h3>${fileRows(d.attachments,share)}<p class="muted">Seules les pièces sélectionnées sont incluses. Aucun accès hors ligne.</p><button data-action="close">Fermer</button>`);}

document.addEventListener('change',e=>{if(e.target.id==='module-organization'){location.href='/s02/rights?organization='+encodeURIComponent(e.target.value)+'#modules';return;}if(e.target.id==='share-target')shareForm(e.target.value);});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.trash){await trashCall(b.dataset.trash,{request:b.dataset.id,...(b.dataset.disposal==='true'?{disposal:true,...(b.dataset.case?{case:b.dataset.case}:{})}:{})});await load();notice('Opération enregistrée. Aucun fichier détruit.');return;}if(b.dataset.action==='trash-request'){trashForm();return;}
 if(b.dataset.action==='partner-new'){partnerForm();return;}if(b.dataset.partnerEdit){partnerForm(Number(b.dataset.partnerEdit)-1);return;}
 if(b.dataset.moduleAction){await moduleAction(b);return;}
 if(b.dataset.action==='agent-new'||b.dataset.agentEdit){registryForm(b.dataset.agentEdit);return;}
 if(b.dataset.action?.startsWith('sup-')){await supportAction(b.dataset.action,b.dataset.id,b);return;}
 if(b.dataset.action==='collection-new'){createCollectionForm();return;}
 if(b.dataset.action?.startsWith('col-')){await collectionAction(b.dataset.action,b.dataset.id,b);return;}
 if(b.dataset.read){await readShared(b.dataset.read,b.dataset.resource);return;}
 if(b.dataset.download){const d=await request('/identity/shares/read',{share:b.dataset.download,resource:b.dataset.resource,download:true});saveBlob(new Blob([JSON.stringify(d.body,null,2)],{type:'text/plain'}),'uniion-partage.txt');return;}
 if(b.dataset.files){const r=a.resources.find(x=>x.id===b.dataset.files);if(!r)throw Error('Accès refusé.');modal('Pièces jointes — '+r.title,fileRows((a.attachments||[]).filter(f=>f.resource===r.id)));return;}
 if(b.dataset.filePreview){await openPreview(b.dataset.filePreview,b.dataset.share||null,1,b.dataset.parent);return;}
 if(b.dataset.previewPage){await openPreview(previewing.id,previewing.share,Number(b.dataset.previewPage),previewing.parent);return;}
 if(b.dataset.previewZoom){const img=$('#modal-body img');if(img)img.style.width=img.style.width==='200%'?'100%':'200%';return;}
 if(b.dataset.fileDownload){await downloadFile(b.dataset.fileDownload,b.dataset.share||null);return;}
 if(b.dataset.org){location.assign('/s02/rights?organization='+encodeURIComponent(b.dataset.org)+'#organisations');return;}
 if(b.id==='switch-org'){if(location.hash==='#organisations')await load();else location.hash='organisations';return;}
 if(b.dataset.view){if(location.hash.slice(1)===b.dataset.view)await load();else location.hash=b.dataset.view;return;}
 if(b.dataset.filter){filter=b.dataset.filter;show();return;}
 if(b.dataset.rights)rights(b.dataset.rights);
 else if(b.dataset.action==='close')close();else if(b.dataset.action==='dismiss')$('#notice').hidden=true;
 else if(b.dataset.action==='new-share')shareForm();else if(b.dataset.action==='directory')await directory();
 else if(b.dataset.accept)accept(b.dataset.accept);
 else if(b.dataset.revoke)modal('Révoquer ce partage ?',`<p>Les accès futurs seront retirés. Les copies déjà téléchargées ne peuvent pas être récupérées.</p><div class="actions"><button data-action="close">Annuler</button><button class="danger" data-confirm-revoke="${b.dataset.revoke}">Confirmer la révocation</button></div>`);
 else if(b.dataset.confirmRevoke){await request('/identity/shares/revoke',{share:b.dataset.confirmRevoke});close();await load();notice('Partage révoqué dans Supabase.');}
 }catch(e){if(reading||previewing)close();notice(e.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const f=e.target,v=new FormData(f);try{if(f.dataset.form==='trash-request'){await trashCall('request',{...(new URL(location.href).searchParams.has('scope')?{link:new URL(location.href).searchParams.get('link')}:{attachment:new URL(location.href).searchParams.get('piece')}),expected:Number(new URL(location.href).searchParams.get('revision')),reason:v.get('reason')});await load();close();notice('Demande transmise au super admin. Le contenu reste accessible jusqu’à validation.');return;}if(f.dataset.form==='partner-save'){await request('/identity/partners/save',{source:v.get('source'),target:v.get('target'),enabled:v.has('enabled')});await load();close();notice('Référentiel actualisé. Aucun accès métier accordé.');return;}if(f.dataset.form==='module-commercial'){await request('/identity/modules/commercial',{module:f.dataset.id,reason:v.get('reason'),from:new Date(v.get('from')).toISOString(),until:new Date(v.get('until')).toISOString()});await load();close();notice('Geste commercial enregistré. Activation et droits métier restent séparés.');return;}if(f.dataset.form==='registry-save'){await request('/identity/support-agents/save',{user_id:v.get('user_id'),name:v.get('name'),enabled:v.has('enabled')});await load();close();notice('Registre des agents actualisé. Aucun accès métier accordé.');return;}if(f.dataset.form==='support-assign')await request('/identity/support/assign',{ticket:f.dataset.id,agents:v.getAll('agents')});if(f.dataset.form==='support-request')await request('/identity/support/request',{ticket:f.dataset.id,reason:v.get('reason')});if(f.dataset.form==='support-approve')await request('/identity/support/approve-files',{attachments:v.getAll('attachments'),ticket:f.dataset.id,agents:v.getAll('agents'),resources:v.getAll('resources'),until:new Date(v.get('expires')).toISOString(),download:v.has('download')});if(f.dataset.form==='support-create')await request('/identity/support/create',{title:v.get('title')});if(f.dataset.form==='collection-create')await request('/identity/collections/create',{target:v.get('target'),name:v.get('name'),color:v.get('color'),text:v.get('text')});if(f.dataset.form==='collection-draft')await run('collectionDraft',{collection:f.dataset.id,color:v.get('color'),text:v.get('text')});if(f.dataset.form==='collection-override')await run('collectionOverride',{collection:f.dataset.id,text:v.get('text')});if(f.dataset.form==='directory'){if(!v.getAll('people').length)throw Error('Sélectionnez au moins un contact.');await request('/identity/consents/change',{target:v.get('target'),grantee:v.get('grantee').trim(),people:v.getAll('people'),until:new Date(v.get('until')).toISOString(),enabled:true});}
if(f.dataset.form==='share'){if(Array.from(f.querySelectorAll('input[name=attachments]:checked')).some(e=>!v.getAll('resources').includes(e.dataset.parent)))throw Error('Sélectionnez la ressource associée à chaque pièce jointe.');await request('/identity/shares/create',{target:v.get('target'),resources:v.getAll('resources'),people:v.getAll('people'),until:new Date(v.get('until')).toISOString(),download:v.has('download'),attachments:v.getAll('attachments'),versions:Object.fromEntries(Array.from(f.querySelectorAll('input[name=resources]:checked')).map(e=>[e.value,Number(e.dataset.version)]))});filter='sent';view='partages';}
if(f.dataset.form==='accept')await request('/identity/shares/accept',{share:f.dataset.share,people:v.getAll('people')});
if(f.dataset.form!=='rights'){if(f.dataset.form.startsWith('support-')){support=await request('/identity/support');show();}else await load();close();notice('Modification enregistrée dans Supabase.');}if(f.dataset.form==='rights'){const m=a.members.find(x=>x.id===f.dataset.user),changes=[];for(const p of s.permissions){const checked=v.getAll('perm').includes(p.module+':'+p.permission),was=m.permissions.some(x=>x.module===p.module&&x.permission===p.permission);if(checked!==was)changes.push({type:'permission',module:p.module,permission:p.permission,enabled:checked});}for(const p of a.authorities.filter(x=>x.delegable)){const checked=v.getAll('authority').includes(p.permission);if(checked!==m.authorities.includes(p.permission))changes.push({type:'authority',permission:p.permission,enabled:checked});}for(const r of a.resources){const old=m.grants.find(g=>g.resource===r.id&&!g.revoked&&Date.parse(g.until)>Date.now()),before=old?(old.write?'write':'read'):'none',next=v.get('resource:'+r.id);if(next!==before)changes.push({type:'resource',resource:r.id,permission:next==='none'?'read':next,enabled:next!=='none',until:new Date(v.get('until')).toISOString(),history:v.has('history')});}if(audiences.manage){const next=v.get('agenda-audience'),before=audiences.members.find(x=>x.user===m.id)?.audience||'none';if(next!==before)changes.push({type:'agenda_audience',permission:next,enabled:next!=='none'});}if(changes.length)await request('/identity/rights/change',{user_id:m.id,changes});await load();close();notice('Habilitations enregistrées dans Supabase.');}}catch(e){f.querySelector('.form-error').textContent=e.message;}finally{busy=false;}});
try{const r=await fetch('/auth/session',{credentials:'same-origin'});const session=await r.json();csrf=session.csrf;if(!session.authenticated||!session.business_allowed)throw Error('Connectez-vous avec MFA depuis l’application S02, puis ouvrez ce parcours.');platformRole=await request('/identity/platform-role');await load();}catch(e){$('#main').textContent=e.message;}

function supportView(){return heading('Support temporaire','Un ticket ne donne aucun accès aux contenus métiers.',platformRole?.superAdmin?'<button data-view="agents-support">Agents support</button>':'')+`${support.member?'<button class="primary" data-action="sup-create">Ouvrir un ticket</button>':''}<div class="grid" style="margin-top:18px">${support.tickets.map(t=>`<section class="card"><span class="tag">${t.state==='open'?'Ouvert':'Clos'}</span><h2>${esc(t.title)}</h2><p class="muted">${t.id} · ${esc(s.organization.name)}</p><div class="actions">${support.manage?(t.state==='open'?`<button data-action="sup-assign" data-id="${t.id}">Affecter les agents</button><button data-action="sup-approve" data-id="${t.id}" ${t.agents.length?'':'disabled'}>Autoriser un accès</button><button data-action="sup-close" data-id="${t.id}">Clore le ticket</button>`:`<button data-action="sup-reopen" data-id="${t.id}">Rouvrir sans réactiver les accès</button>`):t.staff&&t.state==='open'?`<button data-action="sup-request" data-id="${t.id}" ${t.requests.some(q=>q.status==='pending')?'disabled':''}>Demander un accès</button><button data-action="sup-close" data-id="${t.id}">Clore le ticket</button>`:''}</div>${supportRequests(t)}${supportGrants(t)}</section>`).join('')||'<div class="empty">Aucun ticket visible dans cet espace.</div>'}</div><p class="muted">Aucune modification, aucun repartage, aucun accès hors ligne ni connexion au nom de l’utilisateur. La clôture révoque tous les accès ; rouvrir ne les réactive jamais.</p>`;}
async function supportAction(action,id,b){
 const t=support.tickets.find(t=>t.id===id);
 if(action==='sup-file-preview'||action==='sup-file-download'){const input={ticket:id,grant:b.dataset.grant,attachment:b.dataset.attachment};if(action==='sup-file-preview'){const d=await request('/identity/support/files/preview',{...input,page:Number(b.dataset.page||1)});modal(d.filename,`<span class="tag">Aperçu · lecture seule · page ${d.page} / ${d.pages}</span><div class="actions"><button data-action="sup-file-preview" data-id="${id}" data-grant="${input.grant}" data-attachment="${input.attachment}" data-page="${d.page-1}" ${d.page===1?'disabled':''}>Page précédente</button><button data-action="sup-file-preview" data-id="${id}" data-grant="${input.grant}" data-attachment="${input.attachment}" data-page="${d.page+1}" ${d.page===d.pages?'disabled':''}>Page suivante</button></div><figure style="margin:16px 0"><img src="${d.image}" alt="Aperçu de ${esc(d.filename)}, page ${d.page}" style="display:block;width:100%;height:auto;max-width:100%;border:1px solid var(--bd);border-radius:12px"></figure><p class="muted">Le téléchargement du fichier original nécessite une autorisation distincte.</p><button data-action="close">Fermer</button>`);}else{const d=await request('/identity/support/files/download',input);saveBlob(new Blob([Uint8Array.from(atob(d.content),c=>c.charCodeAt(0))],{type:d.mime}),d.filename);}return;}

 if(action==='sup-assign')return modal('Affecter les agents',`<form data-form="support-assign" data-id="${id}"><p>Une affectation permet de suivre ce ticket et de demander un accès. Elle ne donne aucun accès métier. Retirer un agent bloque ses accès existants ; le réaffecter ne les réactive pas.</p><fieldset><legend>Agents nommément désignés</legend>${support.availableAgents.map(a=>`<label class="check"><input type="checkbox" name="agents" value="${a.id}" ${t.agents.some(x=>x.id===a.id)?'checked':''}><span>${esc(a.name)}</span></label>`).join('')}</fieldset><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Enregistrer les affectations</button></div></form>`);
 if(action==='sup-request')return modal('Demander un accès temporaire',`<form data-form="support-request" data-id="${id}"><p>Cette demande ne donne aucun accès. Le métier choisira les ressources et la durée.</p><label class="field"><span>Motif non confidentiel</span><textarea name="reason" maxlength="240" required></textarea></label><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Envoyer la demande</button></div></form>`);
 if(action==='sup-reject'){await request('/identity/support/reject',{ticket:id,request:b.dataset.request});support=await request('/identity/support');show();return notice('Demande refusée. Aucun accès accordé.');}

 if(action==='sup-approve')return modal('Autoriser le support temporaire',`<form data-form="support-approve" data-id="${id}"><p>Ticket : ${esc(t.title)}. L’accès s’arrête à l’expiration ou dès la clôture.</p><fieldset><legend>Agents nommément désignés</legend>${t.agents.map(a=>`<label class="check"><input type="checkbox" name="agents" value="${a.id}" ${b?.dataset.agent===a.id?'checked':''}><span>${esc(a.name)}</span></label>`).join('')}</fieldset><fieldset><legend>Ressources autorisées</legend>${support.resources.map(r=>`<label class="check"><input type="checkbox" name="resources" value="${r.id}"><span>${esc(r.name)}</span></label>`).join('')}</fieldset><fieldset><legend>Pièces jointes à inclure explicitement</legend>${support.attachments.map(a=>`<label class="check"><input type="checkbox" name="attachments" value="${a.id}"><span>${esc(a.filename)}</span></label>`).join('')||'<p class="muted">Aucune pièce jointe disponible.</p>'}<p class="muted">Sélectionnez aussi la ressource associée. Aucun fichier n’est inclus automatiquement.</p></fieldset><label class="field"><span>Expiration obligatoire</span><input name="expires" type="datetime-local" value="${new Date(Date.now()+86400000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}" required></label><label class="check"><input name="download" type="checkbox"><span>Autoriser le téléchargement<small>Une copie téléchargée ne peut pas être récupérée après clôture.</small></span></label><div class="info">Lecture seule. Aucun autre agent ne reçoit cet accès.</div><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Approuver cet accès</button></div></form>`);
 if(action==='sup-revoke')return modal('Révoquer cet accès ?',`<p>Les consultations et téléchargements futurs seront bloqués. Les copies déjà téléchargées ne peuvent pas être récupérées.</p><div class="actions"><button data-action="close">Annuler</button><button class="danger" data-action="sup-revoke-confirm" data-id="${id}" data-grant="${b.dataset.grant}">Confirmer la révocation</button></div>`);
 if(action==='sup-revoke-confirm'){await request('/identity/support/revoke',{ticket:id,grant:b.dataset.grant});support=await request('/identity/support');show();close();return notice('Accès révoqué.');}
 if(action==='sup-read'||action==='sup-download'){const d=await request('/identity/support/read',{ticket:id,grant:b.dataset.grant,resource:b.dataset.resource,download:action==='sup-download'});if(action==='sup-download')saveBlob(new Blob([JSON.stringify(d.body,null,2)],{type:'text/plain'}),'uniion-support.txt');else{modal(d.title,`<span class="tag">Support · lecture seule · version ${d.version}</span><div class="reading">${esc(JSON.stringify(d.body,null,2))}</div><button data-action="close">Fermer</button>`);}return;}

 if(action==='sup-create')return modal('Ouvrir un ticket',`<form data-form="support-create"><p>Décrivez le problème sans contenu métier ni donnée confidentielle.</p><label class="field"><span>Objet du ticket</span><input name="title" maxlength="120" required></label><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Créer le ticket</button></div></form>`);
 if(action==='sup-close')return modal('Clore le ticket ?',`<p>Les consultations et téléchargements futurs seront bloqués. Les copies déjà téléchargées ne peuvent pas être récupérées.</p><div class="actions"><button data-action="close">Annuler</button><button class="danger" data-action="sup-close-confirm" data-id="${id}">Confirmer la clôture</button></div>`);
 if(!['sup-close-confirm','sup-reopen'].includes(action))throw Error('Accès support non raccordé.');
 if(busy)return;busy=true;try{await request('/identity/support/status',{ticket:id,action:action==='sup-reopen'?'reopen':'close'});support=await request('/identity/support');show();close();notice(action==='sup-reopen'?'Ticket rouvert. Une nouvelle approbation est nécessaire.':'Décision enregistrée. Les autorisations ont été actualisées.');}finally{busy=false;}
}

function supportGrants(t){return t.grants.map(g=>`<div class="info"><strong>${g.agents.map(id=>esc(t.agents.find(a=>a.id===id)?.name||'Agent désigné')+(g.excluded?.includes(id)?' · accès retiré':'')).join(', ')}</strong><p>${g.revoked?'Accès révoqué':Date.parse(g.expires)<=Date.now()?'Accès expiré':'Autorisé jusqu’au '+date(g.expires)} · lecture seule · téléchargement ${g.download?'autorisé':'interdit'}</p>${support.manage?`<ul>${g.items.map(r=>`<li>${esc(r.name)} · v${r.version}</li>`).join('')}${g.attachments.map(f=>`<li>${esc(f.filename)}</li>`).join('')}</ul>${!g.revoked&&t.state==='open'?`<button data-action="sup-revoke" data-id="${t.id}" data-grant="${g.id}">Révoquer cet accès</button>`:''}`:t.staff&&t.state==='open'&&!g.revoked&&Date.parse(g.expires)>Date.now()?g.items.map(r=>`<div class="row"><div>${esc(r.name)}</div><button data-action="sup-read" data-id="${t.id}" data-grant="${g.id}" data-resource="${r.id}">Consulter</button><button data-action="sup-download" data-id="${t.id}" data-grant="${g.id}" data-resource="${r.id}" ${g.download?'':'disabled'}>Télécharger</button></div>`).join('')+supportFiles(t,g):''}</div>`).join('')||'<p>Aucun accès métier autorisé.</p>';}

function supportRequests(t){return t.requests.map(q=>`<div class="info"><strong>Demande de ${esc(t.agents.find(a=>a.id===q.agent)?.name||'Agent désigné')}</strong><p>${esc(q.reason)}</p><span class="tag">${({pending:'À approuver',approved:'Approuvée',rejected:'Refusée',cancelled:'Annulée'})[q.status]}</span>${support.manage&&q.status==='pending'&&t.state==='open'?`<div class="actions"><button data-action="sup-approve" data-id="${t.id}" data-agent="${q.agent}">Examiner la demande</button><button data-action="sup-reject" data-id="${t.id}" data-request="${q.id}">Refuser la demande</button></div>`:''}</div>`).join('');}

function supportFiles(t,g){return g.attachments.map(f=>`<div class="row"><div style="overflow-wrap:anywhere"><h3>${esc(f.filename)}</h3><span class="muted">${size(f.size)}</span></div><div class="actions"><button data-action="sup-file-preview" data-id="${t.id}" data-grant="${g.id}" data-attachment="${f.id}" ${f.previewable?'':'disabled'}>Aperçu</button><button data-action="sup-file-download" data-id="${t.id}" data-grant="${g.id}" data-attachment="${f.id}" ${f.downloadable?'':'disabled'}>Télécharger la pièce</button></div></div>`).join('');}

function registryView(){return heading('Agents support','Administration globale réservée au super admin.',`<button class="primary" data-action="agent-new">Ajouter un agent</button>`)+`<div class="info">Le registre ne donne aucun accès aux contenus métiers. Les affectations et autorisations temporaires restent séparées.</div><section class="card">${registry.agents.map(a=>`<div class="row"><div style="overflow-wrap:anywhere"><h3>${esc(a.name)}</h3><p class="muted">${esc(a.id)}</p><span class="tag">${a.active?'Actif':'Désactivé'}</span></div><button data-agent-edit="${a.id}">Modifier</button></div>`).join('')||'<p>Aucun agent enregistré.</p>'}</section>`;}
function registryForm(id){const a=registry.agents.find(x=>x.id===id);modal(a?'Modifier l’agent support':'Ajouter un agent support',`<form data-form="registry-save"><label class="field"><span>Identifiant du compte vérifié</span><input name="user_id" value="${a?.id||''}" ${a?'readonly':''} required pattern="[0-9a-fA-F-]{36}"></label><label class="field"><span>Nom de l’agent</span><input name="name" maxlength="120" value="${esc(a?.name||'')}" required></label><label class="check"><input type="checkbox" name="enabled" ${a?.active?'checked':''}><span>Agent actif</span></label><p class="info">Désactiver retire les affectations, annule les demandes en attente et bloque les anciens accès. Réactiver ne restaure aucun accès. Le compte doit déjà exister et être vérifié.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Enregistrer l’agent</button></div></form>`);}

function modulesView(){return heading('Modules & accès','Chaque module dispose de son propre droit commercial.')+(modules.superAdmin?`<label class="field"><span>Organisation gérée</span><select id="module-organization">${modules.organizations.map(o=>`<option value="${o.id}" ${o.id===organization?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label>`:'')+`<div class="info">Un paiement confirmé ou un geste commercial valide est nécessaire. L’activation locale et les droits métier restent séparés.</div><div class="grid">${modules.modules.map(m=>`<section class="card"><span class="tag ${m.canUse?'good':'warn'}">${m.canUse?'Accessible':!m.available||!m.authorized||!m.eligible?'Accès bloqué':!m.enabled?'À activer':'Droit métier requis'}</span><h2>${esc(m.name)}</h2><ul><li>Catalogue : ${m.available?'disponible':'suspendu'}</li><li>Plateforme : ${m.authorized?'autorisé':'non autorisé'}</li><li>Droit commercial : ${m.eligible?'valide':'absent ou expiré'}</li><li>Activation locale : ${m.enabled?'active':'inactive'}</li><li>Activation déléguée : ${m.delegated?'oui':'non'}</li></ul><div class="actions">${modules.superAdmin?moduleButton(m,'catalog',m.available?'Suspendre au catalogue':'Rétablir au catalogue',!m.available)+moduleButton(m,'authorize',m.authorized?'Retirer l’autorisation':'Autoriser pour cette organisation',!m.authorized)+moduleButton(m,'delegate',m.delegated?'Retirer la délégation locale':'Déléguer l’activation locale',!m.delegated)+moduleButton(m,'commercial','Accorder un geste commercial',true,!m.available||!m.authorized):''}${modules.superAdmin||(modules.manage&&m.delegated)?moduleButton(m,'enable',m.enabled?'Désactiver le module':'Activer le module',!m.enabled,!m.enabled&&(!m.authorized||!m.eligible)):''}${moduleButton(m,'use','Ouvrir le module',true,!m.canUse)}</div><details><summary>Historique des droits commerciaux</summary>${m.entitlements.map(e=>`<p>${e.kind==='paid'?'Paiement confirmé':'Geste commercial'} · ${e.revoked?'révoqué':Date.parse(e.until)<=Date.now()?'expiré':Date.parse(e.from)>Date.now()?'à venir':'valide'}<br>${date(e.from)} → ${date(e.until)}<br>${esc(e.reason||e.reference)}</p>${modules.superAdmin&&e.kind==='commercial'&&!e.revoked?`<button data-module-action="revoke" data-id="${m.id}" data-entitlement="${e.id}">Révoquer le geste commercial</button>`:''}`).join('')||'<p>Aucun droit commercial.</p>'}</details></section>`).join('')}</div>`;}
function moduleButton(m,action,label,enabled,disabled=false){return `<button data-module-action="${action}" data-id="${m.id}" data-enabled="${enabled}" ${disabled?'disabled':''}>${label}</button>`;}
async function moduleAction(b){const module=b.dataset.id,action=b.dataset.moduleAction;
if(action==='commercial'){modal('Accorder un geste commercial',`<form data-form="module-commercial" data-id="${module}"><label class="field"><span>Motif du geste commercial</span><textarea name="reason" maxlength="240" required></textarea></label><label class="field"><span>Début de validité</span><input type="datetime-local" name="from" value="${new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)}" required></label><label class="field"><span>Fin de validité</span><input type="datetime-local" name="until" value="${day()}" required></label><p>Réservé au super admin. Ce droit ne confirme aucun paiement, n’active pas le module et ne donne aucun droit métier.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Confirmer le geste commercial</button></div></form>`);return;}
if(action==='revoke'){modal('Révoquer le geste commercial ?',`<p>L’accès sera bloqué si aucun autre droit commercial valide ne subsiste. Les données sont conservées.</p><div class="actions"><button data-action="close">Annuler</button><button data-module-action="revoke-confirm" data-id="${module}" data-entitlement="${b.dataset.entitlement}">Confirmer la révocation</button></div>`);return;}
b.disabled=true;try{if(action==='use'){if(module==='signature'){notice('Le prestataire de signature électronique reste à raccorder.');return;}await request('/identity/modules/use',{module});location.href='/s02?organization='+encodeURIComponent(organization)+'&screen='+encodeURIComponent(module);return;}if(action==='revoke-confirm'){await request('/identity/modules/revoke',{module,entitlement:b.dataset.entitlement});close();}else await request('/identity/modules/config',{module,action,enabled:b.dataset.enabled==='true'});await load();notice('Accès du module actualisé.');}finally{if(b.isConnected)b.disabled=false;}}

function partnersView(){const name=id=>partners.organizations.find(o=>o.id===id)?.name||id;return heading('Référentiel partenaires','Relations directionnelles entre organisations.',`<button class="primary" data-action="partner-new">Ajouter un partenaire</button>`)+`<div class="info">Réservé au super admin. Un référencement permet de proposer un partage ou une collection, sans ouvrir les contacts ni les contenus. Chaque partage reste explicite et soumis à acceptation.</div><section class="card">${partners.partners.map((p,i)=>`<div class="row"><div><h3>${esc(name(p.source))} → ${esc(name(p.target))}</h3><span class="tag ${p.active?'good':'warn'}">${p.active?'Actif':'Suspendu'}</span><p class="muted">Aucun lien inverse automatique.</p></div><button data-partner-edit="${i+1}">Modifier</button></div>`).join('')||'<p>Aucune relation référencée.</p>'}</section><details><summary>Historique du référentiel</summary>${partners.events.map(e=>`<p>${date(e.at)} · ${esc(name(e.source_id))} → ${esc(name(e.target_id))} · ${e.enabled?'activation':'suspension'}</p>`).join('')||'<p>Aucun événement.</p>'}</details>`;}
function partnerForm(index){const p=partners.partners[index],options=id=>partners.organizations.map(o=>`<option value="${o.id}" ${id===o.id?'selected':''} ${!o.active&&id!==o.id?'disabled':''}>${esc(o.name)}${o.active?'':' · inactive'}</option>`).join('');modal(p?'Modifier le partenaire':'Ajouter un partenaire',`<form data-form="partner-save"><label class="field"><span>Organisation source</span><select name="source" required ${p?'disabled':''}><option value="">Choisir une organisation</option>${options(p?.source)}</select>${p?`<input type="hidden" name="source" value="${p.source}">`:''}</label><label class="field"><span>Organisation destinataire</span><select name="target" required ${p?'disabled':''}><option value="">Choisir une organisation</option>${options(p?.target)}</select>${p?`<input type="hidden" name="target" value="${p.target}">`:''}</label><label class="check"><input type="checkbox" name="enabled" ${!p||p.active?'checked':''}><span>Relation active</span></label><p>La suspension bloque les nouvelles propositions. Les partages déjà consentis restent soumis à leur expiration et à leur révocation explicite. Aucun contenu n’est supprimé.</p><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Enregistrer</button></div></form>`);}

window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'droits';if($('#modal').open)close();$('#main').innerHTML='';load().catch(e=>{$('#main').textContent=e.message;});});

function trashCall(operation,data={}){const url=new URL(location.href),isDisposal=data.disposal||(view!=='suppressions'&&url.searchParams.has('scope')),{disposal,...payload}=data;return request(url.searchParams.get('scope')==='document'?'/identity/documents':'/identity/cases',{action:isDisposal?'disposal':'file_trash',payload:{operation,...(!['admin_list','approve','reject'].includes(operation)?{case:url.searchParams.get('case')}:{}),...payload}});}

function trashView(){const admin=view==='suppressions';return heading(admin?'Validations de suppression':(new URL(location.href).searchParams.get('scope')==='document'?'Corbeille des documents':'Corbeille du dossier'),admin?'Inventaire technique uniquement ; aucun accès aux contenus métier.':'Conservation cible 30 jours. Aucune destruction automatique.',!admin&&(new URL(location.href).searchParams.has('piece')||new URL(location.href).searchParams.has('revision'))?'<button class="primary" data-action="trash-request">Demander la mise en corbeille</button>':'')+'<div class="grid">'+(admin?trash.requests:trash.rows).map(t=>`<section class="card"><h2 style="overflow-wrap:anywhere">${esc(admin?(t.kind||'Pièce')+' '+t.root:t.filename)}</h2><p>${admin?'Organisation : '+esc(t.organization)+' · révision '+t.revision+' · motif '+esc(t.reason):t.state==='pending'?'Validation super admin en attente':'En corbeille depuis '+date(t.deleted)}</p><p class="muted">Retrait réversible. Aucun octet n’est supprimé.</p><div class="actions">${admin?`<button data-trash="approve" data-id="${t.id}" data-disposal="${!!t.disposal}">Approuver la mise en corbeille</button><button data-trash="reject" data-id="${t.id}" data-disposal="${!!t.disposal}">Refuser</button>`:t.state==='approved'?`<button data-trash="restore" data-id="${t.request}" data-disposal="${!!t.case}" data-case="${t.case||''}">Restaurer</button>`:''}</div></section>`).join('')+'</div><p class="muted">Les droits actuels restent obligatoires pour restaurer. Les révocations ne sont pas annulées.</p>';}
function trashForm(){modal('Demander la mise en corbeille',`<form data-form="trash-request"><p>Le contenu restera accessible jusqu’à validation du super admin. Les données et les droits seront conservés.</p><label class="field"><span>Motif</span><select name="reason" required><option value="obsolete">Document obsolète</option><option value="duplicate">Doublon</option><option value="other">Autre motif</option></select></label><p class="form-error" role="alert"></p><div class="actions"><button type="button" data-action="close">Annuler</button><button class="primary">Transmettre la demande</button></div></form>`);}
